pragma solidity ^0.8.10;

import {AccessControlled} from "@mgv-strats/src/strategies/utils/AccessControlled.sol";
import {IOfferLogic} from "@mgv-strats/src/strategies/interfaces/IOfferLogic.sol";
import {MgvLib, IERC20, OLKey, OfferDetail} from "@mgv/src/core/MgvLib.sol";
import {IMangrove} from "@mgv/src/IMangrove.sol";
import {AbstractRouter, RL} from "@mgv-strats/src/strategies/routers/abstract/AbstractRouter.sol";
import {TransferLib} from "@mgv/lib/TransferLib.sol";
import {Tick} from "@mgv/lib/core/TickLib.sol";

/// @title This contract is the basic building block for Mangrove strats.
/// @notice It contains the mandatory interface expected by Mangrove (`IOfferLogic` is `IMaker`) and enforces additional functions implementations (via `IOfferLogic`).
/// @dev Naming scheme:
/// `f() public`: can be used, as is, in all descendants of `this` contract
/// `_f() internal`: descendant of this contract should provide a public wrapper for this function, with necessary guards.
/// `__f__() virtual internal`: descendant of this contract should override this function to specialize it to the needs of the strat.

abstract contract MangroveOffer is AccessControlled, IOfferLogic {
  ///@notice The Mangrove deployment that is allowed to call `this` for trade execution and posthook.
  IMangrove public immutable MGV;

  /// @notice router contract which implements routing functions -- this can be 0x in Direct strats
  AbstractRouter public immutable ROUTER_IMPLEMENTATION;

  ///@notice The offer was successfully reposted.
  bytes32 internal constant REPOST_SUCCESS = "offer/updated";
  ///@notice New offer successfully created.
  bytes32 internal constant NEW_OFFER_SUCCESS = "offer/created";
  ///@notice The offer was completely filled.
  bytes32 internal constant COMPLETE_FILL = "offer/filled";

  ///@notice Mandatory function to allow `this` to receive native tokens
  ///@dev this happens when `this` calls `withdrawFromMangrove` with `deprovision=true` or if `this` becomes the recipient of a `makerExecute` bounty.
  receive() external payable virtual {}

  /**
   * @notice `MangroveOffer`'s constructor
   * @param mgv The Mangrove deployment that is allowed to call `this` for trade execution and posthook.
   * @param routerImplementation sets the type of router that the router factory can spawn
   */
  constructor(IMangrove mgv, AbstractRouter routerImplementation) AccessControlled(msg.sender) {
    require(address(mgv) != address(0), "MgvOffer/0xMangrove");
    MGV = mgv;
    ROUTER_IMPLEMENTATION = routerImplementation; // this may be 0x
  }

  ///*****************************
  /// Mandatory callback functions
  ///*****************************

  ///@notice `makerExecute` is the callback function to execute all offers that were posted on Mangrove by `this` contract.
  ///@param order a data structure that recapitulates the taker order and the offer as it was posted on mangrove
  ///@return ret a bytes32 word to pass information (if needed) to the posthook (under `result.makerData`)
  ///@dev it may not be overriden although it can be customized using `__lastLook__`, `__put__` and `__get__` hooks.
  /// NB #1: if `makerExecute` reverts, the offer will be considered to be refusing the trade.
  /// NB #2: `makerExecute` may return a `bytes32` word to pass information to posthook w/o using storage reads/writes.
  /// NB #3: Reneging on trade will have the following effects:
  /// * Offer is removed from the Offer List
  /// * Offer bounty will be withdrawn from offer provision and sent to the offer taker. The remaining provision will be credited to `this` contract's account on Mangrove
  function makerExecute(MgvLib.SingleOrder calldata order)
    external
    override
    onlyCaller(address(MGV))
    returns (bytes32 ret)
  {
    // Invoke hook that implements a last look check during execution - it may renege on trade by reverting.
    ret = __lastLook__(order);
    // Invoke hook to put the inbound_tkn, which are brought by the taker, into a specific reserve.
    require(__put__(order.takerGives, order) == 0, "mgvOffer/abort/putFailed");
    // Invoke hook to fetch the outbound_tkn, which are promised to the taker, from a specific reserve.
    require(__get__(order.takerWants, order) == 0, "mgvOffer/abort/getFailed");
  }

  /// @notice `makerPosthook` is the callback function that is called by Mangrove *after* the offer execution.
  /// @notice reverting during its execution will not renege on trade. Revert reason (casted to 32 bytes) is then logged by Mangrove in event `PosthookFail`.
  /// @param order a data structure that recapitulates the taker order and the offer as it was posted on mangrove
  /// @param result a data structure that gathers information about trade execution
  /// @dev It cannot be overridden but can be customized via the hooks `__posthookSuccess__`, `__posthookFallback__` and `__handleResidualProvision__` (see below).
  function makerPosthook(MgvLib.SingleOrder calldata order, MgvLib.OrderResult calldata result)
    external
    override
    onlyCaller(address(MGV))
  {
    if (result.mgvData == "mgv/tradeSuccess") {
      __posthookSuccess__(order, result.makerData);
    } else {
      // logging what went wrong during `makerExecute`
      emit LogIncident(order.olKey.hash(), order.offerId, result.makerData, result.mgvData);
      // calling strat specific handlers in case of failure
      __posthookFallback__(order, result);
      __handleResidualProvision__(order);
    }
  }

  ///@notice whether this contract has enabled liquidity routing
  ///@return true if this contracts routes liquidity using an external router
  function _isRouting() internal view returns (bool) {
    return address(ROUTER_IMPLEMENTATION) != address(0);
  }

  ///@notice takes care of status for reposting residual offer in case of a partial fill and logging of potential issues.
  ///@param order a recap of the taker order
  ///@param makerData generated during `makerExecute` so as to log it if necessary
  ///@param repostStatus from the posthook that handles residual reposting
  function logRepostStatus(MgvLib.SingleOrder calldata order, bytes32 makerData, bytes32 repostStatus) internal {
    // reposting below density is not considered an incident in order to allow the contract not to check density before posting residual
    if (
      repostStatus == COMPLETE_FILL || repostStatus == REPOST_SUCCESS || repostStatus == "mgv/writeOffer/density/tooLow"
    ) {
      return;
    } else {
      // Offer failed to repost for bad reason, logging the incident
      emit LogIncident(order.olKey.hash(), order.offerId, makerData, repostStatus);
    }
  }

  /// @inheritdoc IOfferLogic
  function approve(IERC20 token, address spender, uint amount) public override onlyAdmin returns (bool) {
    require(TransferLib.approveToken(token, spender, amount), "mgvOffer/approve/failed");
    return true;
  }

  /// @inheritdoc IOfferLogic
  function withdrawFromMangrove(uint amount, address payable receiver) public onlyAdmin {
    if (amount == type(uint).max) {
      amount = MGV.balanceOf(address(this));
    }
    // the require below is necessary if the `receive()` function is overriden
    require(MGV.withdraw(amount), "mgvOffer/withdrawFail");
    (bool noRevert,) = receiver.call{value: amount}("");
    // if `receiver` is actually not payable
    require(noRevert, "mgvOffer/weiTransferFail");
  }

  ///@notice Hook that implements where the inbound token, which are brought by the Offer Taker, should go during Taker Order's execution.
  ///@param amount of `inbound` tokens that are on `this` contract's balance and still need to be deposited somewhere
  ///@param order is a recall of the taker order that is at the origin of the current trade.
  ///@return missingPut (<=`amount`) is the amount of `inbound` tokens whose deposit location has not been decided (possibly because of a failure) during this function execution
  ///@dev if the last nested call to `__put__` returns a non zero value, trade execution will revert
  function __put__(uint amount, MgvLib.SingleOrder calldata order) internal virtual returns (uint missingPut);

  ///@notice Hook that implements where the outbound token, which are promised to the taker, should be fetched from, during Taker Order's execution.
  ///@param amount of `outbound` tokens that still needs to be brought to the balance of `this` contract when entering this function
  ///@param order is a recall of the taker order that is at the origin of the current trade.
  ///@return missingGet (<=`amount`), which is the amount of `outbound` tokens still need to be fetched at the end of this function
  ///@dev if the last nested call to `__get__` returns a non zero value, trade execution will revert
  function __get__(uint amount, MgvLib.SingleOrder calldata order) internal virtual returns (uint missingGet);

  /// @notice Hook that implements a last look check during Taker Order's execution.
  /// @param order is a recall of the taker order that is at the origin of the current trade.
  /// @return data is a message that will be passed to posthook provided `makerExecute` does not revert.
  /// @dev __lastLook__ should revert if trade is to be reneged on. If not, returned `bytes32` are passed to `makerPosthook` in the `makerData` field.
  /// @custom:hook overrides of this hook should be conservative and call `super.__lastLook__(order)`.
  function __lastLook__(MgvLib.SingleOrder calldata order) internal virtual returns (bytes32 data) {
    order; //shh
    data = bytes32(0);
  }

  /// @inheritdoc IOfferLogic
  function activate(IERC20 token) public virtual override {
    require(TransferLib.approveToken(token, address(MGV), type(uint).max), "MgvOffer/ActivationFailed");
  }

  ///@notice Post-hook that implements fallback behavior when Taker Order's execution failed unexpectedly.
  ///@param order is a recall of the taker order that is at the origin of the current trade.
  ///@param result contains information about trade.
  ///@return data contains verdict and reason about the executed trade.
  ///@dev `result.mgvData` is Mangrove's verdict about trade success
  ///@dev `result.makerData` either contains the first 32 bytes of revert reason if `makerExecute` reverted or the returned `bytes32`.
  /// @custom:hook overrides of this hook should be conservative and call `super.__posthookFallback__(order, result)`
  function __posthookFallback__(MgvLib.SingleOrder calldata order, MgvLib.OrderResult calldata result)
    internal
    virtual
    returns (bytes32 data)
  {
    order;
    result;
    data = bytes32(0);
  }

  ///@notice Given the current taker order that (partially) consumes an offer, this hook is used to declare how much `order.olKey.outbound_tkn` the offer gives after it is reposted, while also allowing adjustment to the tick.
  ///@param order is a recall of the taker order that is being treated.
  ///@return newGives the new volume of `outbound_tkn` the offer will give if fully taken.
  ///@return newTick the new tick of the reposted offer.
  ///@dev default is to require the original amount of tokens minus those that have been sent to the taker during trade execution and keep the tick.
  function __residualValues__(MgvLib.SingleOrder calldata order) internal virtual returns (uint newGives, Tick newTick) {
    newGives = order.offer.gives() - order.takerWants;
    newTick = order.offer.tick();
  }

  ///@notice Hook that defines what needs to be done to the part of an offer provision that was added to the balance of `this` on Mangrove after an offer has failed.
  ///@param order is a recall of the taker order that failed
  function __handleResidualProvision__(MgvLib.SingleOrder calldata order) internal virtual {
    order; // we leave the provision on Mangrove
  }

  ///@notice Post-hook that implements default behavior when Taker Order's execution succeeded.
  ///@param order is a recall of the taker order that is at the origin of the current trade.
  ///@param makerData is the returned value of the `__lastLook__` hook, triggered during trade execution. The special value `"lastLook/retract"` should be treated as an instruction not to repost the offer on the list.
  ///@return data can be:
  /// * `COMPLETE_FILL` when offer was completely filled
  /// * returned data of `_updateOffer` signalling the status of the reposting attempt.
  /// @custom:hook overrides of this hook should be conservative and call `super.__posthookSuccess__(order, maker_data)`
  function __posthookSuccess__(MgvLib.SingleOrder calldata order, bytes32 makerData)
    internal
    virtual
    returns (bytes32 data)
  {
    // now trying to repost residual
    (uint newGives, Tick newTick) = __residualValues__(order);
    // Density check at each repost would be too gas costly.
    // We only treat the special case of `gives==0` or `wants==0` (total fill).
    // Note: wants (given by `inboundFromOutbound`) can be 0 due to rounding given the price. We could repost to get rid of the last gives at 0 wants,
    // but the maker does not need to give away these tokens for free, so we skip it.
    // Offer below the density will cause Mangrove to throw so we encapsulate the call to `updateOffer` in order not to revert posthook for posting at dust level.
    if (newGives == 0 || newTick.inboundFromOutbound(newGives) == 0) {
      return COMPLETE_FILL;
    }
    data = _updateOffer(
      OfferArgs({
        olKey: order.olKey,
        tick: newTick,
        gives: newGives,
        gasreq: order.offerDetail.gasreq(),
        gasprice: order.offerDetail.gasprice(),
        noRevert: true,
        fund: 0
      }),
      order.offerId
    );
    // logs if anything went wrong
    logRepostStatus(order, makerData, data);
  }

  ///@notice Updates the offer specified by `offerId` on Mangrove with the parameters in `args`.
  ///@param args A memory struct containing the offer parameters to update.
  ///@param offerId An unsigned integer representing the identifier of the offer to be updated.
  ///@return status a `bytes32` value representing either `REPOST_SUCCESS` if the update is successful, or an error message if an error occurs and `OfferArgs.noRevert` is `true`. If `OfferArgs.noRevert` is `false`, the function reverts with the error message as the reason.
  function _updateOffer(OfferArgs memory args, uint offerId) internal virtual returns (bytes32);

  ///@notice computes the provision that can be redeemed if deprovisioning a certain offer
  ///@param olKey the offer list key.
  ///@param offerId the id of the offer
  ///@return provision the provision that can be redeemed
  function _provisionOf(OLKey memory olKey, uint offerId) internal view returns (uint provision) {
    OfferDetail offerDetail = MGV.offerDetails(olKey, offerId);
    unchecked {
      provision = offerDetail.gasprice() * 1e6 * (offerDetail.offer_gasbase() + offerDetail.gasreq());
    }
  }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.18;

import {IMangrove} from "@mgv/src/IMangrove.sol";
import {
  RenegingForwarder,
  MangroveOffer,
  Tick,
  RouterProxyFactory,
  RouterProxy
} from "@mgv-strats/src/strategies/offer_forwarder/RenegingForwarder.sol";
import {TransferLib, RL} from "@mgv-strats/src/strategies/MangroveOffer.sol";
import {IOrderLogic} from "@mgv-strats/src/strategies/interfaces/IOrderLogic.sol";
import {SmartRouter, AbstractRoutingLogic} from "@mgv-strats/src/strategies/routers/SmartRouter.sol";

import {MgvLib, IERC20, OLKey} from "@mgv/src/core/MgvLib.sol";

///@title MangroveOrder. A periphery contract to Mangrove protocol that implements "Good Til Cancel" orders, "Good Til Cancel Enforced" orders, "Post Only" orders, "Immediate Or Cancel" orders, and "Fill Or Kill" orders,
///@notice A GTC order is a buy (sell) limit order complemented by a bid (ask) limit order, called a resting order, that occurs when the buy (sell) order was partially filled.
/// If the GTC is for some amount $a_goal$ at a price $p$, and the corresponding limit order was partially filled for $a_now < a_goal$,
/// the resting order should be posted for an amount $a_later = a_goal - a_now$ at price $p$.
/// If the resting order fails to be posted, the transaction wont fail.
///@notice A GTCE order mimics a GTC order, but shall the resting order fail to be posted, the transaction will revert.
///@notice A PO order is a buy (sell) limit order that is only posted and is not ran against the market.
///@notice An IOC order is a buy (sell) limit order that is ran against the market for a partial or complete fill and no resting order will be posted.
///@notice A FOK order is simply a buy or sell limit order that is either completely filled or cancelled. No resting order is posted.
contract MangroveOrder is RenegingForwarder, IOrderLogic {
  ///@notice MangroveOrder is a Forwarder logic with a smart router.
  ///@param mgv The mangrove contract on which this logic will run taker and maker orders.
  ///@param factory the router proxy factory used to deploy or retrieve user routers
  ///@param deployer The address of the admin of `this` at the end of deployment
  constructor(IMangrove mgv, RouterProxyFactory factory, address deployer)
    RenegingForwarder(mgv, factory, new SmartRouter(address(this)))
  {
    _setAdmin(deployer);
  }

  ///@notice compares a taker order with a market order result and checks whether the order was entirely filled
  ///@param tko the taker order
  ///@param res the market order result
  ///@return true if the order was entirely filled, false otherwise.
  function checkCompleteness(TakerOrder calldata tko, TakerOrderResult memory res) internal pure returns (bool) {
    // The order can be incomplete if the price becomes too high or the end of the book is reached.
    if (tko.fillWants) {
      // when fillWants is true, the market order stops when `fillVolume` units of `outbound_tkn` have been obtained (minus potential fees);
      return res.takerGot + res.fee >= tko.fillVolume;
    } else {
      // otherwise, the market order stops when `fillVolume` units of `tko.olKey.inbound_tkn` have been sold.
      return res.takerGave >= tko.fillVolume;
    }
  }

  ///@inheritdoc IOrderLogic
  function take(TakerOrder calldata tko) external payable returns (TakerOrderResult memory res) {
    // Checking whether order is expired
    require(tko.expiryDate == 0 || block.timestamp < tko.expiryDate, "mgvOrder/expired");
    (RouterProxy proxy,) = ROUTER_FACTORY.instantiate(msg.sender, ROUTER_IMPLEMENTATION);
    SmartRouter userRouter = SmartRouter(address(proxy));

    // Notations:
    // NAT_USER: initial value of `msg.sender.balance` (native balance of user)
    // OUT/IN_USER: initial value of `userRouter.tokenBalanceOf({token: tko.[out|in]bound_tkn, fundOwner:msg.sender})
    // NAT_THIS: initial value of `address(this).balance` (native balance of `this`)
    // OUT/IN_THIS: initial value of `tko.[out|in]bound_tkn.balanceOf(address(this))` (`this` balance of tokens)

    logOrderData(tko); // for indexing
    bool isComplete; // stores whether market order is filled
    // this will check if this isn't a post only offer for the market order
    if (tko.orderType.executesMarketOrder()) {
      // State before market order:
      // * User balances: (NAT_USER -`msg.value`, OUT_USER, IN_USER)
      // * `this` balances: (NAT_THIS +`msg.value`, OUT_THIS, IN_THIS)
      (res, isComplete) = executeMarketOrder(tko, userRouter);
      // State after market order:
      // * (NAT_USER-`msg.value`, OUT_USER+`res.takerGot`, IN_USER-`res.takerGave`)
      // * (NAT_THIS+`msg.value`+`res.bounty`, OUT_THIS, IN_THIS)

      // NB: for post only orders, we will keep the same semantic for the state of balances
      // However in the case of post only, since `res.bounty` == `res.takerGot` == `res.takerGave` == 0,
      // the state of balances can be annotated the same as before the market order.
    }

    ///@dev collected bounty compensates gas consumption for the failed offer, but could be lower than the cost of an additional native token transfer
    /// instead of sending the bounty back to `msg.sender` we recycle it into the resting order's provision (so `msg.sender` can retrieve it when deprovisioning).
    /// corner case: if the bounty is large enough, this will make posting of the resting order fail because of `gasprice` overflow.
    /// The funds would then be sent back to `msg.sender` (see below).
    uint fund = msg.value + res.bounty;

    if ( // resting order is:
      tko.orderType.postRestingOrder(isComplete) // required
    ) {
      // When posting a resting order `msg.sender` (taker) becomes a maker.
      // For maker orders, outbound tokens are what makers send. Here `msg.sender` sends `tko.olKey.inbound_tkn`.
      // The offer list on which this contract must post `msg.sender`'s resting order is thus `tko.olKey.flipped()`
      // the call below will continue filling the memory data `res`.
      fund = postRestingOrder({tko: tko, olKey: tko.olKey.flipped(), res: res, userRouter: userRouter, fund: fund});
      // POST (case `postRestingOrder` succeeded):
      // * (NAT_USER-`msg.value`, OUT_USER+`res.takerGot`, IN_USER-`res.takerGave`)
      // * (NAT_THIS, OUT_THIS, IN_THIS)
      // * `fund == 0`
      // * `ownerData[tko.olKey.flipped().hash()][res.offerId].owner == msg.sender`.
      // * Mangrove emitted an `OfferWrite` log whose `maker` field is `address(this)` and `offerId` is `res.offerId`.

      // POST (case `postRestingOrder` failed):
      // * (NAT_USER-`msg.value`, OUT_USER+`res.takerGot`, IN_USER-`res.takerGave`)
      // * (NAT_THIS+`msg.value`+`res.bounty`, OUT_THIS, IN_THIS)
      // * `fund == msg.value + res.bounty`.
      // * `res.offerId == 0`
    }

    if (fund > 0) {
      // NB this calls gives reentrancy power to callee, but OK since:
      // 1. callee is `msg.sender` so no griefing risk of making this call fail for out of gas
      // 2. w.r.t reentrancy for profit:
      // * from POST above a reentrant call would entail either:
      //   - `fund == 0` (no additional funds transferred)
      //   - or `fund == msg.value + res.bounty` with `msg.value` being from reentrant call and `res.bounty` from a second resting order.
      // Thus no additional fund can be redeemed by caller using reentrancy.
      (bool noRevert,) = msg.sender.call{value: fund}("");
      require(noRevert, "mgvOrder/refundFail");
    }
    // POST (case `postRestingOrder` succeeded)
    // * (NAT_USER, OUT_USER+`res.takerGot`, IN_USER-`res.takerGave`)
    // * (NAT_THIS, OUT_THIS, IN_THIS)
    // POST (else)
    // * (NAT_USER+`res.bounty`, OUT_USER+`res.takerGot`, IN_USER-`res.takerGave`)
    // * (NAT_THIS, OUT_THIS, IN_THIS)
    emit MangroveOrderComplete();
    return res;
  }

  ///@notice logs `MangroveOrderStart`
  ///@param tko the arguments in memory of the taker order
  ///@dev this function avoids loading too many variables on the stack
  function logOrderData(TakerOrder memory tko) internal {
    emit MangroveOrderStart({
      olKeyHash: tko.olKey.hash(),
      taker: msg.sender,
      tick: tko.tick,
      orderType: tko.orderType,
      fillVolume: tko.fillVolume,
      fillWants: tko.fillWants,
      offerId: tko.offerId,
      takerGivesLogic: tko.takerGivesLogic,
      takerWantsLogic: tko.takerWantsLogic
    });
  }

  /// @notice Executes a market order on Mangrove according to the taker order.
  /// @param tko arguments in memory of the taker order
  /// @param userRouter the user router
  /// @return res the result of the market order
  /// @return isComplete true if the order was entirely filled, false otherwise.
  /// @dev tko.orderType must not be PO
  function executeMarketOrder(TakerOrder calldata tko, SmartRouter userRouter)
    internal
    returns (TakerOrderResult memory res, bool isComplete)
  {
    // `pullAmount` is derived in `execute` of core protocol to ensure same behavior.
    uint pullAmount = tko.fillWants ? tko.tick.inboundFromOutboundUp(tko.fillVolume) : tko.fillVolume;
    // Pulling funds from `msg.sender`'s routing policy
    RL.RoutingOrder memory inboundRoute = RL.createOrder({fundOwner: msg.sender, token: IERC20(tko.olKey.inbound_tkn)});
    if (address(tko.takerGivesLogic) != address(0)) {
      // telling router to use `takerGivesLogic` when `inboundRoute` is selected
      userRouter.setLogic(inboundRoute, tko.takerGivesLogic);
    }
    require(userRouter.pull(inboundRoute, pullAmount, true) == pullAmount, "mgvOrder/transferInFail");

    // Executes a market order on Mangrove
    (res.takerGot, res.takerGave, res.bounty, res.fee) =
      MGV.marketOrderByTick({olKey: tko.olKey, maxTick: tko.tick, fillVolume: tko.fillVolume, fillWants: tko.fillWants});

    // Current state:
    // * (NAT_USER-`msg.value`, OUT_USER, IN_USER-`takerGives`)
    // * (NAT_THIS+`msg.value`+`res.bounty`, OUT_THIS+`res.takerGot`, IN_THIS+`takerGives`-`res.takerGave`)

    // Checking whether order was entirely filled
    isComplete = checkCompleteness(tko, res);

    // we check whether the order was entirely filled before posting the resting order
    // if the order is a FoK and was not entirely filled, we revert.
    // if the order is GTC(E) or IOC, the market order succeeds.
    // in all cases, if the market order is filled, we do not revert (Here we assume no PO orders are passed to this function)
    require(tko.orderType.marketOrderSucceded(isComplete), "mgvOrder/partialFill");

    RL.RoutingOrder memory outboundRoute;
    if (res.takerGot > 0) {
      // routing outbound token (received by taker) according to takerWantsLogic
      // We approve the user router to pull `takerGot` outbound tokens from this contract.
      TransferLib.approveToken(IERC20(tko.olKey.outbound_tkn), address(userRouter), res.takerGot);
      // pushing tokens received during market order
      outboundRoute = RL.createOrder({token: IERC20(tko.olKey.outbound_tkn), fundOwner: msg.sender});
      if (address(tko.takerWantsLogic) != address(0)) {
        // telling router to use `takerWantsLogic` when `outboundRoute` is selected.
        userRouter.setLogic(outboundRoute, tko.takerWantsLogic);
      }
      require(userRouter.push(outboundRoute, res.takerGot) == res.takerGot, "mgvOrder/pushFailed");
      // set back router's storage to 0 for some cheap gas refund
      if (address(tko.takerWantsLogic) != address(0)) {
        userRouter.setLogic(outboundRoute, AbstractRoutingLogic(address(0)));
      }
    }
    // we now deal with inbound left in case the order was partially filled
    uint inboundLeft = pullAmount - res.takerGave;
    if (inboundLeft > 0) {
      TransferLib.approveToken(IERC20(tko.olKey.inbound_tkn), address(userRouter), inboundLeft);
      // Here we can use `inboundRoute`.
      require(userRouter.push(inboundRoute, inboundLeft) == inboundLeft, "mgvOrder/pushFailed");
    }
    // set back router's storage to 0 for some cheap gas refund
    if (address(tko.takerGivesLogic) != address(0)) {
      userRouter.setLogic(inboundRoute, AbstractRoutingLogic(address(0)));
    }
  }

  ///@notice posts a maker order on the (`olKey`) offer list.
  ///@param tko the arguments in memory of the taker order
  ///@param olKey the offer list key.
  ///@param fund amount of WEIs used to cover for the offer bounty (covered gasprice is derived from `fund`).
  ///@param userRouter the user router
  ///@param res the result of the taker order.
  ///@return refund the amount to refund to the taker of the fund.
  ///@dev if relative limit price of taker order is `ratio` in the (outbound_tkn, inbound_tkn) offer list (represented by `tick=log_{1.0001}(ratio)` )
  ///@dev then entailed relative price for resting order must be `1/ratio` (relative price on the (inbound_tkn, outbound_tkn) offer list)
  ///@dev so with ticks that is `-log(ratio)`, or -tick.
  ///@dev the price of the resting order should be the same as for the max price for the market order.
  function postRestingOrder(
    TakerOrder calldata tko,
    OLKey memory olKey,
    TakerOrderResult memory res,
    SmartRouter userRouter,
    uint fund
  ) internal returns (uint refund) {
    // computing hash in advance
    bytes32 olKeyHash = olKey.hash();

    // computing residual values
    Tick residualTick = Tick.wrap(-Tick.unwrap(tko.tick));
    uint residualGives;
    if (tko.fillWants) {
      // partialFill => tko.fillVolume > res.takerGot + res.fee
      uint residualWants = tko.fillVolume - (res.takerGot + res.fee);
      // adapting residualGives to match relative limit price chosen by the taker
      residualGives = residualTick.outboundFromInboundUp(residualWants);
    } else {
      // partialFill => tko.fillVolume > res.takerGave
      residualGives = tko.fillVolume - res.takerGave;
    }
    OfferArgs memory args = OfferArgs({
      olKey: olKey,
      tick: residualTick,
      gives: residualGives,
      gasreq: tko.restingOrderGasreq,
      gasprice: 0, // ignored
      fund: fund,
      noRevert: true // returns `(0,reason)` if MGV reverts
    });
    if (tko.offerId == 0) {
      // posting a new offer
      (res.offerId, res.offerWriteData) = _newOffer(args, msg.sender);
    } else {
      // updating an existing offer
      uint offerId = tko.offerId;
      // checking ownership of offer since we use internal version of `updateOffer` which is unguarded
      require(ownerData[olKeyHash][offerId].owner == msg.sender, "AccessControlled/Invalid");
      // msg sender might have given an offerId that is already live
      // we disallow this to avoid confusion
      require(!MGV.offers(olKey, offerId).isLive(), "mgvOrder/offerAlreadyActive");
      res.offerWriteData = _updateOffer(args, offerId);
      if (res.offerWriteData == REPOST_SUCCESS) {
        res.offerId = offerId;
      } else {
        res.offerId = 0;
      }
    }
    if (res.offerId == 0) {
      // either:
      // - residualGives is below current density
      // - `fund` is too low and would yield a gasprice that is lower than Mangrove's
      // - `fund` is too high and would yield a gasprice overflow
      // - offer list is not active (Mangrove is not dead otherwise market order would have reverted)
      // So the resting order was not posted.
      // If GTC is enforced (GTCE) or if the order is PO we revert.
      require(!tko.orderType.enforcePostRestingOrder(), "mgvOrder/RestingOrderFailed");
      // `fund` is no longer needed so sending it back to `msg.sender`
      refund = fund;
    } else {
      // offer was successfully posted
      // `fund` was used and we leave `refund` at 0.
      // update or create routes for the given offer if needed
      RL.RoutingOrder memory route = RL.RoutingOrder({
        token: IERC20(olKey.outbound_tkn),
        fundOwner: msg.sender,
        olKeyHash: olKeyHash,
        offerId: res.offerId
      });
      if (address(tko.takerGivesLogic) != address(0)) {
        // because the taker becomes the maker, the outbound token logic is the takerGivesLogic
        userRouter.setLogic(route, tko.takerGivesLogic);
      }
      // updating route for inbound token
      route.token = IERC20(olKey.inbound_tkn);
      if (address(tko.takerWantsLogic) != address(0)) {
        // because the taker becomes the maker, the inbound token logic is the takerWantsLogic
        userRouter.setLogic(route, tko.takerWantsLogic);
      }

      // setting expiry date for the resting order
      if (tko.expiryDate > 0) {
        _setReneging(olKeyHash, res.offerId, tko.expiryDate, 0);
      }
    }
  }
}

